describe('File Upload Progress Bar', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display progress bar and update as file is uploaded', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload/file', {
      statusCode: 200,
      body: {
        fileId: '12345',
        fileSize: 1024 * 1024,
        status: 'success'
      }
    }).as('uploadFile');

    // Select file input and upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });

    // Verify progress bar is visible
    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('have.class', 'progress-bar');

    // Verify initial progress is 0%
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow', '0');

    // Wait for file upload API call
    cy.wait('@uploadFile');

    // Verify progress bar updates
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow', '50');

    // Verify progress bar reaches 100%
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow', '100');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify file is listed in uploads
    cy.get('[data-testid="uploads-list"]').should('be.visible');
    cy.get('[data-testid="upload-item"]').should('contain', 'test-file.pdf');
  });

  it('should handle file upload interruption and show error state', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload/file', {
      statusCode: 500,
      body: {
        error: 'Server error occurred during upload'
      }
    }).as('uploadFileError');

    // Select file input and upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });

    // Verify progress bar is visible
    cy.get('[data-testid="progress-bar"]').should('be.visible');

    // Wait for file upload API call
    cy.wait('@uploadFileError');

    // Verify progress bar does not reach 100%
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow', '50');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');

    // Verify file is not listed in uploads
    cy.get('[data-testid="uploads-list"]').should('not.exist');
  });
});
